validator:
function validate([n]) {
  if (!Number.isInteger(n) || n < 0 || n > 1e9) return 'n is a whole number from 0 to 10^9.';
  return null;
}

reference:
function baseNeg2(n) {
  if (n === 0) {
    return '0';
  }
  const digits = [];
  while (n !== 0) {
    const bit = n & 1;
    digits.push(bit);
    n = (n - bit) / -2;
  }
  return digits.reverse().join('');
}

brute:
function baseNeg2(n) {
  // Independent trick: adding then xoring a mask of the odd bit positions turns
  // ordinary binary weights 2^k into (-2)^k.
  const mask = 0xAAAAAAAAAAAAn;
  const digits = ((BigInt(n) + mask) ^ mask).toString(2);
  let value = 0;
  for (let k = 0; k < digits.length; k++) value += Number(digits[digits.length - 1 - k]) * (-2) ** k;
  if (value !== n) throw new Error('mask trick failed');
  return digits;
}

generator:
function generate(rand, size) {
  if (size === 'large') return [Math.floor(rand() * 1e9) + 1];
  const roll = rand();
  if (roll < 0.6) return [Math.floor(rand() * 64)];
  if (roll < 0.9) return [Math.floor(rand() * 100000)];
  return [1e9 - Math.floor(rand() * 1000)];
}
